    if m == 0:
        return 1
    if m == 1:
        return n - 1

    # Dynamic programming table
    dp = [[0] * (m + 1) for _ in range(n + 1)]

    # Fill the base cases
    for i in range(n + 1):
        dp[i][0] = 1
    for i in range(n + 1):
        for j in range(1, i + 1):
            dp[i][j] = i * dp[i][j-1]

    for i in range(2, n + 1):
        for j in range(1, m + 1):
            dp[i][j] = dp[i-1][j-1] * (i - j) + dp[i-1][j] * j

